//! Cross-language vectors are generated by scripts/pine_broker_parity_fixtures.py.
use super::*;

#[test]
fn disabled_quantization_identity_matches_python_without_invalidating_legacy_state() {
    let config = json!({"script":"ma.pine", "quantize_strategy_orders":false});
    let canonical = json!({"script":"ma.pine"});
    let participant = json!({"participant_id":"a"});
    let expected =
        digest(&json!({"source":"source", "config":canonical, "participant":participant})).unwrap();
    assert_eq!(
        schema_two_identity("source", &config, &participant, &Value::Null).unwrap(),
        expected
    );
    let legacy =
        digest(&json!({"source":"source", "config":config, "participant":participant})).unwrap();
    let saved = json!({"broker_schema":2,"identity":legacy});
    assert_eq!(
        schema_two_identity("source", &config, &participant, &saved).unwrap(),
        legacy
    );
    let changed = json!({"script":"edited.pine", "quantize_strategy_orders":false});
    assert_ne!(
        schema_two_identity("source", &changed, &participant, &saved).unwrap(),
        legacy
    );
}

#[test]
fn python_broker_grid_close_cancel_and_replacement_vectors() {
    let rows: Value = serde_json::from_str(include_str!(
        "../../../python/tests/fixtures/pine_broker_direct.json"
    ))
    .unwrap();
    for row in rows.as_array().unwrap() {
        let frozen = row["state"].clone();
        let mut state = frozen.clone();
        let views: Vec<_> = row["views"].as_array().unwrap().iter().collect();
        let result = broker::translate(
            row["intents"].as_array().unwrap(),
            2,
            &views,
            &row["config"],
            &mut state,
        )
        .and_then(|mut actions| {
            actions.extend(broker::replacements(&mut state, &views, &row["config"])?);
            Ok(json!({"actions": actions, "state": state}))
        });
        if row["error"] == true {
            assert!(result.is_err(), "{}", row["name"]);
        } else {
            assert_eq!(result.unwrap(), row["expected"], "{}", row["name"]);
        }
        assert_eq!(row["state"], frozen);
    }
}

#[test]
fn ecosystem_history_route_boundary_does_not_limit_original_sources() {
    assert!(history_profile(false, 128, 128));
    assert!(!history_profile(false, 129, 128));
    assert!(history_profile(true, 8192, 128));
}

#[test]
fn python_exit_protection_order_rounding_latch_retry_cancel_and_wake_vectors() {
    let rows: Value = serde_json::from_str(include_str!(
        "../../../python/tests/fixtures/pine_exit_direct.json"
    ))
    .unwrap();
    for row in rows.as_array().unwrap() {
        let mut state = row["state"].clone();
        let views: Vec<_> = row["views"].as_array().unwrap().iter().collect();
        let result = broker::translate(
            row["intents"].as_array().unwrap(),
            2,
            &views,
            &row["config"],
            &mut state,
        )
        .and_then(|mut actions| {
            actions.extend(broker::finish(&mut state, &views, &row["config"], true)?);
            Ok(json!({"actions":actions,"state":state}))
        });
        if row["error"] == true {
            assert!(result.is_err(), "{}: {result:?}", row["name"]);
        } else {
            assert_eq!(
                result.unwrap_or_else(|e| panic!("{}: {e:?}", row["name"])),
                row["expected"],
                "{}",
                row["name"]
            );
        }
    }
}

#[test]
fn restored_exit_state_requires_separate_source_qualification() {
    let host = Host::load(
        &std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../bot-plugins/pine-strategy"),
    )
    .unwrap();
    let state = json!({"exit_specs":{"owned":{}}});
    assert!(host.exit_profile(
        &json!({"script":"ecosystem/library/fcbb24e7080c73f4.pine"}),
        &state
    ));
    for script in [
        "ma.pine",
        "ecosystem/library/0068dd1dd9576132.pine",
        "ecosystem/library/179a641fbb9d2f08.pine",
        "ecosystem/library/660e65aadf0a9b74.pine",
        "ecosystem/library/952d678dd81772a2.pine",
    ] {
        assert!(
            !host.exit_profile(&json!({"script":script}), &state),
            "{script}"
        );
    }
    assert!(!host.exit_profile(
        &json!({"script":"ecosystem/library/fcbb24e7080c73f4.pine"}),
        &json!({"exit_specs":[]})
    ));
    assert!(!host.exit_profile(
        &json!({"script":"ecosystem/library/fcbb24e7080c73f4.pine"}),
        &json!({"exit_specs":{"first":{},"second":{}}})
    ));
    assert!(!host.source_is_current("ecosystem/library/660e65aadf0a9b74.pine"));
}
